mapper.select:
select  from crm_offer

    and product_code like concat('%', #{productCode}, '%')
    and sheet_name like concat('%', #{sheetName}, '%')

        and

            product_code like concat(#{code}, '%')



        and (

            supplier_code = #{sc}

        )

    and inq_offer_type = #{inqOfferType}

        and (

            product_brand like concat('%', #{pb}, '%')

        )


        and (

            product_type like concat('%', #{pt}, '%')

        )


        and id in

             #{pt}


    and tags_first like concat('%', #{tagsFirst}, '%')
    and tags_second like concat('%', #{tagsSecond}, '%')
    and tags_third like concat('%', #{tagsThird}, '%')
    and tags_si like concat('%', #{tagsSi}, '%')
    and create_time >= #{params.lastCreateTime}
    and stock_date >= concat(#{params.beginStockDate}, ' 00:00:00')
    and stock_date <= concat(#{params.endStockDate}, ' 23:59:59')
    and price_cost >= #{params.minPriceCost}
    and price_cost <= #{params.maxPriceCost}
    and price_offer >= #{params.minPriceOffer}
    and price_offer <= #{params.maxPriceOffer}
    and quantity >= #{params.minQuantity}
    and quantity <= #{params.maxQuantity}

order by update_time desc

select from crm_offer where coalesce(stock_date, create_time) >= date_sub(now(), interval 1 month) and inq_offer_type in ('Inq','Offer') and (
upper(product_code) like concat(#{code}, '%')
) order by product_code asc, coalesce(stock_date, create_time) desc, id desc

select from crm_offer where coalesce(stock_date, create_time) >= date_sub(curdate(), interval (#{days} - 1) day) and coalesce(stock_date, create_time) <= now() and inq_offer_type = 'Offer' and (
upper(product_code) = #{code}
) order by product_code asc, price_offer asc, coalesce(stock_date, create_time) desc

select from crm_offer where coalesce(stock_date, create_time) >= date_sub(now(), interval 1 month) and inq_offer_type in ('Inq','Offer') and (
upper(product_code) = #{code}
) order by coalesce(stock_date, create_time) desc, id desc

mapper.insert:
insert into crm_offer(
    product_code, product_brand, stock_date, product_detail, price_cost, price_offer, price_unit,
    quantity, delivery_time, remark, sheet_name, moq_quantity, warranty_detail, dc, supplier_code, supplier_name,
    tags_first, tags_second, tags_third, tags_si, status, create_time, update_time, create_by, update_by, product_type, product_detail_code, inq_offer_type
) values (
    upper(#{productCode}), #{productBrand}, #{stockDate}, #{productDetail}, #{priceCost}, #{priceOffer}, #{priceUnit},
    #{quantity}, #{deliveryTime}, #{remark}, #{sheetName}, #{moqQuantity}, #{warrantyDetail}, #{dc}, #{supplierCode}, #{supplierCode},
    #{tagsFirst}, #{tagsSecond}, #{tagsThird}, #{tagsSi}, #{status}, now(), now(), #{createBy}, #{updateBy}, #{productType}, upper(#{productDetailCode}), #{inqOfferType}
)

mapper.update:
update crm_offer
product_brand = #{offer.productBrand}, stock_date = #{offer.stockDate}, product_detail = #{offer.productDetail}, price_cost = #{offer.priceCost}, price_offer = #{offer.priceOffer}, price_unit = #{offer.priceUnit}, quantity = #{offer.quantity}, delivery_time = #{offer.deliveryTime}, moq_quantity = #{offer.moqQuantity}, warranty_detail = #{offer.warrantyDetail}, remark = #{offer.remark}, tags_first = #{offer.tagsFirst}, tags_second = #{offer.tagsSecond}, tags_third = #{offer.tagsThird}, tags_si = #{offer.tagsSi}, product_type = #{offer.productType}, product_detail_code = upper(#{offer.productDetailCode}), inq_offer_type = #{offer.inqOfferType}, update_time = now()
where id in #{id}
